    [21337] = {21337, "Foyer of Corruption", [[ A foyer of flames of Corruption dealing 6500 damage of magic of fire within a radius of 8 yd. all the 2 sec. ]], 0, 0, 317668, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21338] = {21338, "Tir of barrage", [[ Ouvre of the portails of where jaillissent of puissants flux magiques, dealing 12500 damage to the enemies in ligne droite and the knocking back of 10 yd. ]], 0, 0, 317685, 11661, 21341, 21339, 0, 1, 48, 2, 2, -1, 0},
    [21339] = {21339, "Tir of barrage of the Darkness", [[ Ouvre a portal of where jaillit a powerful flux of Darkness, dealing 12500 damage of magic of the darkness to the enemies in ligne droite and the knocking back of 10 yd. ]], 0, 0, 317669, 11661, 21340, 0, 0, 1, 0, 2, 2, -1, 0},
    [21340] = {21340, "Tir of barrage of the Corruption", [[ Ouvre a portal of where jaillit a powerful flux of Corruption, dealing 12500 damage of magic of fire to the enemies in ligne droite and the knocking back of 10 yd. ]], 0, 0, 317671, 11661, 0, 0, 0, 1, 0, 2, 2, -1, 0},
    [21341] = {21341, "Hit sismique", [[ Strikes the target, dealing 180000 physical damage distributed between the targets within a radius of 8 yd., and ébranle the pièce, launching all enemies to 10 yd. ]], 0, 0, 317673, 11661, 21342, 0, 0, 1, 33, 2, 2, -1, 0},
    [21342] = {21342, "Shadows hurlantes", [[ Deals 10000 physical damage to all enemies and interrompt their incantations during 5 sec. ]], 0, 0, 317674, 11661, 21343, 0, 0, 1, 0, 2, 2, -1, 0},
    [21343] = {21343, "Magic déferlante", [[ Strikes the enemy of magic during 15 sec. All the 3 sec., of the "Puits of the Darkness" or of the "Foyers of Corruption" appear under the target, selon the marque that it was bearing. ]], 0, 0, 317675, 11661, 0, 0, 0, 1, 1, 2, 2, -1, 0},
    [21530] = {21530, "Norigorn", [[ A mystérieux artefact ancien, a montagne vivante of pierre façonnée selon a logique étrange and inexplicable - some pierres semblent not have never been hit by a main, tandis that of other paraissent habilement taillées by a maçon for bâtir a forteresse. The origine of Norigorn demeure inconnue, and the mages-chercheurs modernes débattent without fin of the principes magiques that animent this guardian. A chose, however, does the unanimité : Norigorn itself acquitte more that honorablement of its tâche and can aisément vaincre same the aventuriers solitaires the more puissants that convoiteraient its trésors. ]], 557969, 0, 0, 11672, 21537, 21531, 0, 1, 0, 2, 2, -1, 70010},
    [21531] = {21531, "Attraction of power", [[ The death of the enemies of the caster of spells causes a resonance of the lignes telluriques, lui restituant 1% of its health all the 3 sec. and increasing its attack speed of 100%. ]], 0, 0, 317620, 11672, 21532, 0, 0, 0, 32, 2, 2, -1, 0},
    [21532] = {21532, "Afflux of power", [[ The death of the enemies of the caster of spells causes a resonance of the lignes telluriques, lui restituant 1% of its health all the 3 seconds. ]], 0, 0, 317621, 11672, 21533, 0, 0, 0, 160, 2, 2, -1, 0},
    [21533] = {21533, "Resonance of power", [[ The death of the enemies of the caster of spells causes a resonance of the lignes telluriques, increasing its attack speed of 100% during 10 seconds. ]], 0, 0, 317622, 11672, 21534, 0, 0, 0, 0, 2, 2, -1, 0},
    [21534] = {21534, "Discharge in chain", [[ A discharge of foudre jaillit of the caster of spells, striking the enemy désigné then bondissant towards of other enemies nearby, dealing 12000 damage to each one. Effectue 4 sauts. The damage of the discharge not diminuent not after each saut. ]], 0, 0, 317623, 11672, 21535, 0, 0, 0, 0, 2, 2, -1, 0},
    [21535] = {21535, "Poing aiguisé by the vents", [[ A puissante attacks of melee dealing 50000 physical damage to the enemy, the mutilant and transperçant its armor. The valeur of armor of the enemy diminue of 12%, and its reserve maximum of health of 10%. Se stacks up to 8 times. ]], 0, 0, 317273, 11672, 21536, 0, 0, 0, 33, 2, 2, -1, 0},
    [21536] = {21536, "Taillade fulgurante", [[ the caster charge its body of décharges électriques, itself accélérant considérablement during a court instant, this that lui permet of exécuter a attacks circulaire dévastatrice dealing 40000 physical damage to all enemies within a radius of 10 yards. ]], 0, 0, 317274, 11672, 0, 0, 0, 0, 32, 2, 2, -1, 0},
    [21537] = {21537, "Phase 1 : Appel of the elements", [[ Norigorn between in combat contre ceux that have empiété on its territoire, puisant in the sources of the elements primordiaux for se renforcer. ]], 0, 0, 0, 11672, 21547, 21538, 0, 1, 0, 2, 2, -1, 0},
    [21538] = {21538, "Renaissance of the earth", [[ Summoning of a pilier of protection of the Earth. ]], 0, 0, 317266, 11672, 21541, 21539, 0, 0, 0, 2, 2, -1, 0},
    [21539] = {21539, "Aiguille de la Terre", [[  ]], 565122, 0, 0, 11672, 0, 21540, 0, 0, 0, 2, 2, -1, 83221},
    [21540] = {21540, "Bienveillance of the Forteresse", [[ Empoisonnées by the blood versé, the terres have entendu the appel, restituant to Norigorn 500000 health all the 2 sec. ]], 0, 0, 317301, 11672, 0, 0, 0, 0, 34, 2, 2, -1, 0},
    [21541] = {21541, "Renaissance of the fire", [[ Summoning of a pilier of protection of the Fire. ]], 0, 0, 317267, 11672, 21544, 21542, 0, 0, 0, 2, 2, -1, 0},
    [21542] = {21542, "Aiguille du Feu", [[  ]], 565123, 0, 0, 11672, 0, 21543, 0, 0, 0, 2, 2, -1, 83222},
    [21543] = {21543, "Persévérance of the Fire", [[ The parenté with the depths enflamme the rage and the anger jadis éteintes of Norigorn, increasing of 20% the damage that it deals. ]], 0, 0, 317302, 11672, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21544] = {21544, "Renaissance of the vents", [[ Summoning of a pilier of protection of the Vents. ]], 0, 0, 317268, 11672, 0, 21545, 0, 0, 0, 2, 2, -1, 0},
    [21545] = {21545, "Aiguille des Vents", [[  ]], 565124, 0, 0, 11672, 0, 21546, 0, 0, 0, 2, 2, -1, 83223},
    [21546] = {21546, "Infinité of the Vents", [[ The vents enveloppent Norigorn, lui accordant protection and sérénité, reducing of 30% the damage that it suffers. ]], 0, 0, 317303, 11672, 0, 0, 0, 0, 34, 2, 2, -1, 0},
    [21547] = {21547, "Phase 2 : Acceptation of the nature", [[ Ayant subi of importants damage, Norigorn summons to its aide of the creatures of the earth, then becomes invulnerable and begins to absorber the essence circulant to travers the lignes telluriques. ]], 0, 0, 0, 11672, 21552, 21548, 0, 1, 0, 2, 2, -1, 0},
    [21548] = {21548, "Acceptation of the nature", [[ the caster attire the energy of a ligne tellurique dissimulée under earth, then se met to the absorber during 60 sec. During the absorption, the caster is totalement invulnerable, but not can rien do of other that maintenir this absorption. To the moment of utiliser Acceptation of the nature, Norigorn summons depuis the depths of the earth 10 spiders of the lignes telluriques for the protéger. ]], 0, 0, 317275, 11672, 21551, 21549, 0, 0, 0, 2, 2, -1, 0},
    [21549] = {21549, "Spider of the lignes telluriques", [[  ]], 34068, 0, 0, 11672, 0, 21550, 0, 0, 1, 2, 2, -1, 70014},
    [21550] = {21550, "Endurance primordiale", [[ The creature of the earth has assimilé the energy résiduelle of the ligne tellurique and transmet the charge of its strength nouvellement acquise to its créateur, increasing its reserve maximum of health of 4% up to the fin of the combat. Se stacks up to 10 times. ]], 0, 0, 317277, 11672, 0, 0, 0, 0, 0, 2, 2, -1, 0},
    [21551] = {21551, "Énergies instables", [[ When Norigorn uses Acceptation of the nature, the Aiguilles of the Earth, of the Fire and of the Vents existantes débordent of energy inutilisée. The energy instable of the ligne tellurique jaillit periodically, dealing 2500 damage of magic arcane all the 1 sec. ]], 0, 0, 317285, 11672, 0, 0, 0, 0, 6, 2, 2, -1, 0},
    [21552] = {21552, "Phase 3 : Renversement", [[ After have achevé the absorption of the essence of the lignes telluriques, Norigorn returns to the combat in using its new abilities. ]], 0, 0, 0, 11672, 0, 21553, 0, 1, 0, 2, 2, -1, 0},
    [21553] = {21553, "Aiguille of recréation", [[ Summoning of a aiguille of recréation. ]], 0, 0, 317278, 11672, 21556, 21554, 0, 0, 0, 2, 2, -1, 0},
