    [21558] = {21558, "Shard of destruction", [[ the caster déverse the energy négative accumulée on all enemies, dealing to each one 20000 damage of the forces of the darkness. ]], 0, 0, 317281, 11672, 0, 0, 0, 0, 102, 2, 2, -1, 0},
    [21559] = {21559, "Séisme devastating", [[ the caster secoue the earth, retournant the ground under the pieds of its enemies in a déchaînement of énergies telluriques. player pris in the séisme suffer 10000 physical damage all the 3 sec. and are affected by "Stun", that increases of 33% the physical damage suffered all the 3 sec. ]], 0, 0, 317624, 11672, 0, 0, 0, 0, 32, 2, 2, -1, 0},
    [21560] = {21560, "Lacération of the aile", [[ Deals $[2 30848$]$[1 30848$] damage to the enemies in a sector in front of the caster, the knocking back in rear. This hit ignores the armor of the enemy. ]], 0, 0, 69293, 1651, 11403, 0, 0, 0, 0, 2, 2, 2, 0},
